CREATE TABLE organization_bans (
  id text PRIMARY KEY,
  organization_id text NOT NULL,
  user_id text NOT NULL,
  banned_by text,
  reason text NOT NULL,
  created_at timestamptz NOT NULL,
  lifted_at timestamptz,
  lifted_by text,
  FOREIGN KEY (lifted_by) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (banned_by) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE
);

CREATE TABLE organization_members (
  organization_id text NOT NULL,
  user_id text NOT NULL,
  member_role text NOT NULL DEFAULT 'member',
  joined_at timestamptz NOT NULL,
  PRIMARY KEY (organization_id, user_id),
  CHECK (member_role IN ('member', 'student_organizer', 'manager')),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE
);

CREATE TABLE password_reset_tokens (
  token_hash text PRIMARY KEY,
  user_id text NOT NULL,
  expires_at timestamptz NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE reauth_challenges (
  id text PRIMARY KEY,
  user_id text NOT NULL,
  "action" text NOT NULL,
  params_hash text NOT NULL,
  method text,
  session_jti text NOT NULL,
  created_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  granted_at timestamptz,
  consumed_at timestamptz,
  attempts integer NOT NULL DEFAULT 0,
  ip_hash text,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE recovery_codes (
  id text PRIMARY KEY,
  user_id text NOT NULL,
  code_hash text NOT NULL,
  used_at timestamptz,
  created_at timestamptz NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE report_evidence (
  report_id text NOT NULL,
  message_id text NOT NULL,
  sender_id text,
  sender_name_snapshot text,
  body text NOT NULL,
  created_at timestamptz NOT NULL,
  captured_at timestamptz NOT NULL,
  PRIMARY KEY (report_id, message_id),
  FOREIGN KEY (report_id) REFERENCES reports(id) ON DELETE RESTRICT
);

CREATE TABLE resend_webhook_events (
  event_id text PRIMARY KEY,
  event_type text NOT NULL,
  provider_message_id text,
  recipient_domain text,
  occurred_at timestamptz,
  received_at timestamptz NOT NULL,
  job_id text
);

CREATE TABLE revoked_sessions (
  jti text PRIMARY KEY,
  user_id text NOT NULL,
  revoked_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL
);

CREATE TABLE schema_migrations (
  version integer PRIMARY KEY,
  name text NOT NULL,
  applied_at timestamptz NOT NULL,
  checksum text
);

CREATE TABLE security_audit_logs (
  id text PRIMARY KEY,
  user_id text NOT NULL,
  event_type text NOT NULL,
  ip_address text,
  user_agent text,
  metadata text,
  created_at timestamptz NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE tfa_email_codes (
  id text PRIMARY KEY,
  user_id text NOT NULL,
  code_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  attempts integer DEFAULT 0,
  used_at timestamptz,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE tfa_login_attempts (
  token_hash text PRIMARY KEY,
  user_id text NOT NULL,
  attempts integer DEFAULT 0,
  last_attempt_at timestamptz NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE user_badges (
  id text PRIMARY KEY,
  user_id text NOT NULL,
  badge_id text NOT NULL,
  earned_at timestamptz NOT NULL,
  awarded_by text,
  UNIQUE (user_id, badge_id),
  FOREIGN KEY (badge_id) REFERENCES badges(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE user_blocks (
  id text PRIMARY KEY,
  blocker_id text NOT NULL,
  blocked_id text NOT NULL,
  created_at timestamptz NOT NULL,
  FOREIGN KEY (blocked_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (blocker_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE user_capabilities (
  user_id text NOT NULL,
  capability text NOT NULL,
  scope text NOT NULL DEFAULT '',
  granted_by text NOT NULL,
  granted_at timestamptz NOT NULL,
  expires_at timestamptz,
  PRIMARY KEY (user_id, capability, scope),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE user_favorites (
  user_id text NOT NULL,
  event_id text NOT NULL,
  created_at timestamptz NOT NULL,
  PRIMARY KEY (user_id, event_id),
  FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE user_relationships (
  id text PRIMARY KEY,
  actor_id text NOT NULL,
  subject_id text NOT NULL,
  kind text NOT NULL,
  status text NOT NULL DEFAULT 'accepted',
  created_at timestamptz NOT NULL,
  responded_at timestamptz,
  CHECK (kind IN ('friend', 'mute', 'restrict')),
  CHECK (status IN ('pending', 'accepted')),
  CHECK (actor_id <> subject_id),
  UNIQUE (actor_id, subject_id, kind),
  FOREIGN KEY (subject_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE CASCADE
);

