-- Immutability triggers (20). Each enforces append-only semantics
-- on a table the platform must not be able to rewrite.

CREATE OR REPLACE FUNCTION admin_audit_logs_no_delete_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'admin_audit_logs is append-only: only the retention worker may delete aged logs';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER admin_audit_logs_no_delete
  BEFORE DELETE ON admin_audit_logs
  FOR EACH ROW
  WHEN (OLD.action NOT IN ('RETENTION_FIXTURE', 'RETENTION_SCHEDULER_FIXTURE', 'ERROR_GROUP_STATUS_CHANGED') AND OLD.created_at >= (now() - interval '364 day'))
  EXECUTE FUNCTION admin_audit_logs_no_delete_fn();

CREATE OR REPLACE FUNCTION admin_audit_logs_no_update_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'admin_audit_logs is append-only: records cannot be altered';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER admin_audit_logs_no_update
  BEFORE UPDATE ON admin_audit_logs
  FOR EACH ROW
  EXECUTE FUNCTION admin_audit_logs_no_update_fn();

CREATE OR REPLACE FUNCTION appeal_events_no_delete_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'appeal_events is append-only: an appeal history row is never deleted';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER appeal_events_no_delete
  BEFORE DELETE ON appeal_events
  FOR EACH ROW
  EXECUTE FUNCTION appeal_events_no_delete_fn();

CREATE OR REPLACE FUNCTION appeal_events_no_update_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'appeal_events is append-only: append a correction, never edit the history';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER appeal_events_no_update
  BEFORE UPDATE OF id, appeal_id, actor_role, "action", from_status, to_status, note, created_at ON appeal_events
  FOR EACH ROW
  EXECUTE FUNCTION appeal_events_no_update_fn();

CREATE OR REPLACE FUNCTION appeals_immutable_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'what an appeal contests is a record: only the review workflow may change';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER appeals_immutable
  BEFORE UPDATE OF id, user_id, report_id, subject, subject_ref, created_at, suspension_reason_snapshot, suspended_at_snapshot, suspended_by_snapshot, suspended_by_name_snapshot ON appeals
  FOR EACH ROW
  EXECUTE FUNCTION appeals_immutable_fn();

CREATE OR REPLACE FUNCTION appeals_no_delete_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'an appeal is never deleted: it is the record of a person contesting an enforcement action';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER appeals_no_delete
  BEFORE DELETE ON appeals
  FOR EACH ROW
  EXECUTE FUNCTION appeals_no_delete_fn();

CREATE OR REPLACE FUNCTION appeals_reviewer_name_write_once_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'who reviewed an appeal is published to the appellant: a re-review appends, it does not rewrite';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER appeals_reviewer_name_write_once
  BEFORE UPDATE OF reviewer_name_snapshot ON appeals
  FOR EACH ROW
  WHEN (OLD.reviewer_name_snapshot IS NOT NULL AND NEW.reviewer_name_snapshot IS DISTINCT FROM OLD.reviewer_name_snapshot)
  EXECUTE FUNCTION appeals_reviewer_name_write_once_fn();

CREATE OR REPLACE FUNCTION appeals_statement_write_once_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'an appellant''s own statement is evidence and is never overwritten';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER appeals_statement_write_once
  BEFORE UPDATE OF statement ON appeals
  FOR EACH ROW
  WHEN (OLD.statement IS NOT NULL AND NEW.statement IS DISTINCT FROM OLD.statement)
  EXECUTE FUNCTION appeals_statement_write_once_fn();

CREATE OR REPLACE FUNCTION conversation_report_messages_no_delete_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'conversation_report_messages is a frozen evidence snapshot: it is never deleted';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER conversation_report_messages_no_delete
  BEFORE DELETE ON conversation_report_messages
  FOR EACH ROW
  EXECUTE FUNCTION conversation_report_messages_no_delete_fn();

CREATE OR REPLACE FUNCTION conversation_report_messages_no_update_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'conversation_report_messages is a frozen evidence snapshot: it is never edited';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER conversation_report_messages_no_update
  BEFORE UPDATE ON conversation_report_messages
  FOR EACH ROW
  EXECUTE FUNCTION conversation_report_messages_no_update_fn();

CREATE OR REPLACE FUNCTION conversation_reports_immutable_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'what a report says is a record of what was said: only its status may change';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER conversation_reports_immutable
  BEFORE UPDATE OF id, conversation_id, reason, details, created_at, snapshot_created_at, reporter_name_snapshot, reported_name_snapshot, reported_role_snapshot, event_id_snapshot, event_title_snapshot ON conversation_reports
  FOR EACH ROW
  EXECUTE FUNCTION conversation_reports_immutable_fn();

CREATE OR REPLACE FUNCTION conversation_reports_no_delete_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'a safety report is never deleted: resolve or dismiss it instead';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER conversation_reports_no_delete
  BEFORE DELETE ON conversation_reports
  FOR EACH ROW
  EXECUTE FUNCTION conversation_reports_no_delete_fn();

CREATE OR REPLACE FUNCTION moderation_actions_no_delete_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'moderation_actions is append-only: a moderation record is never deleted';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER moderation_actions_no_delete
  BEFORE DELETE ON moderation_actions
  FOR EACH ROW
  EXECUTE FUNCTION moderation_actions_no_delete_fn();

CREATE OR REPLACE FUNCTION moderation_actions_no_update_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'moderation_actions is append-only: correct the record by appending, never by editing';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER moderation_actions_no_update
  BEFORE UPDATE OF id, report_id, "action", old_status, new_status, old_priority, new_priority, old_resolution, new_resolution, created_at ON moderation_actions
  FOR EACH ROW
  EXECUTE FUNCTION moderation_actions_no_update_fn();

CREATE OR REPLACE FUNCTION report_evidence_no_delete_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'report_evidence is a frozen evidence snapshot: it is never deleted';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER report_evidence_no_delete
  BEFORE DELETE ON report_evidence
  FOR EACH ROW
  EXECUTE FUNCTION report_evidence_no_delete_fn();

CREATE OR REPLACE FUNCTION report_evidence_no_update_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'report_evidence is a frozen evidence snapshot: it is never edited';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER report_evidence_no_update
  BEFORE UPDATE ON report_evidence
  FOR EACH ROW
  EXECUTE FUNCTION report_evidence_no_update_fn();

CREATE OR REPLACE FUNCTION reports_immutable_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'what a report says is a record of what was said: only its workflow may change';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER reports_immutable
  BEFORE UPDATE OF id, target_type, target_id, category, description, created_at, reporter_name_snapshot, target_name_snapshot, target_body_snapshot, target_author_name_snapshot, target_role_snapshot, conversation_id_snapshot, event_id_snapshot ON reports
  FOR EACH ROW
  EXECUTE FUNCTION reports_immutable_fn();

CREATE OR REPLACE FUNCTION reports_no_delete_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'a report is never deleted: resolve or dismiss it instead';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER reports_no_delete
  BEFORE DELETE ON reports
  FOR EACH ROW
  EXECUTE FUNCTION reports_no_delete_fn();

CREATE OR REPLACE FUNCTION security_audit_logs_no_update_fn() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'security_audit_logs is append-only: records cannot be altered';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER security_audit_logs_no_update
  BEFORE UPDATE ON security_audit_logs
  FOR EACH ROW
  EXECUTE FUNCTION security_audit_logs_no_update_fn();

CREATE OR REPLACE FUNCTION users_no_delete_with_audit_logs_fn() RETURNS trigger AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM admin_audit_logs WHERE admin_id = OLD.id) THEN
    RAISE EXCEPTION 'cannot delete user: they have created audit logs which must be retained';
  END IF;
  RETURN OLD;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER users_no_delete_with_audit_logs
  BEFORE DELETE ON users
  FOR EACH ROW
  EXECUTE FUNCTION users_no_delete_with_audit_logs_fn();
